/**
 * WhatsApp message generated by the CONFIRMAÇÃO PARA FOTO card on an order.
 * The destination and individualized token always come from the existing card.
 * No appointment date/time is invented when the order does not have one.
 */
export interface PhotoConfirmationWhatsappMessageInput {
  customerName?: string | null;
  slotDate?: string | null;
  slotTime?: string | null;
  link: string;
}

function appointmentDate(value?: string | null): string {
  if (!value) return "";
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  return match ? match[3] + "/" + match[2] + "/" + match[1] : value;
}

export function buildPhotoConfirmationWhatsappMessage(
  { customerName, slotDate, slotTime, link }: PhotoConfirmationWhatsappMessageInput,
): string {
  const name = String(customerName || "Cliente").replace(/[\r\n\t]+/g, " ").trim() || "Cliente";
  const date = appointmentDate(slotDate);
  const time = slotTime ? slotTime.slice(0, 5) : "";

  return [
    "👤 *" + name + "*",
    "",
    "🇨🇴 *H2 COLOMBIANO*",
    "📸 *CONFIRMAÇÃO PARA FOTO*",
    "",
    ...(date || time ? [
      "📅 *AGENDAMENTO DA FOTO*",
      ...(date ? ["🗓️ Data: *" + date + "*"] : []),
      ...(time ? ["🕒 Horário: *" + time + "*"] : []),
      "",
    ] : []),
    "🚨 *OBRIGATÓRIO ANTES DA FOTO*",
    "",
    "Para continuar o procedimento,",
    "você precisa:",
    "",
    "1️⃣ Abrir o link abaixo.",
    "2️⃣ *Responder TODAS as perguntas.*",
    "3️⃣ *Finalizar e confirmar*",
    "suas respostas no formulário.",
    "",
    "⚠️ *ATENÇÃO*",
    "A confirmação completa é",
    "*obrigatória antes de fazer a foto.*",
    "",
    "👇 *ACESSE E CONFIRME:*",
    link.trim(),
    "",
    "🛡️ *EQUIPE H2 COLOMBIANO* 🇨🇴",
  ].join("\n");
}
